use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::{unit_step, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, remember, within, FlowError, Scope, Tenant};
use lgwks_bot::task::{task, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let tenant = Tenant::new("recovery").map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder("recovery")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let run = RunId::from_hex(&run_hex(&store_dir)).map_err(|_| RecoveryError::NoStore)?;

    let failed = Arc::new(AtomicU32::new(u32::MAX));

    let body = {
        let w = world.clone();
        let f = Arc::clone(&failed);
        move |scope: Scope, _input: ()| {
            let w = w.clone();
            let f = Arc::clone(&f);
            async move { run_units(&w, &scope, &f).await }
        }
    };

    let t = task("recover", body).map_err(|_| RecoveryError::NoStore)?;

    let scope = Scope::root(tenant);

    let outcome = within(&scope, "recover", deadline, async {
        Ok::<_, FlowError>(host.resume(run, &t, ()).await)
    })
    .await;

    let report = match outcome {
        Ok(report) => report,
        Err(e) => {
            return Err(if e.is_cancelled() || matches!(&e, FlowError::TimedOut { .. }) {
                RecoveryError::Deadline
            } else {
                RecoveryError::NoStore
            });
        }
    };

    match report.into_result() {
        Ok(total) => {
            let ledger = world.ledger();
            if !ledger.applied("recover") {
                ledger.apply("recover");
            }
            Ok(total)
        }
        Err(e) => {
            if e.is_cancelled() || matches!(&e, FlowError::TimedOut { .. }) {
                Err(RecoveryError::Deadline)
            } else {
                let index = failed.load(Ordering::SeqCst);
                if index != u32::MAX {
                    Err(RecoveryError::Unit { index })
                } else {
                    Err(RecoveryError::NoStore)
                }
            }
        }
    }
}

async fn run_units(
    world: &World,
    scope: &Scope,
    failed: &Arc<AtomicU32>,
) -> Result<u64, FlowError> {
    let width = world.width();

    let body = {
        let w = world.clone();
        let f = Arc::clone(failed);
        move |step: Scope, index: u32| {
            let w = w.clone();
            let f = Arc::clone(&f);
            async move {
                let inner = step.enter("r")?;
                let name = unit_step(index);
                let outcome = remember(&inner, &name, || async {
                    w.unit(&step, index)
                        .await
                        .map_err(|_| FlowError::failed("unit failed"))
                })
                .await;
                match outcome {
                    Ok(value) => Ok(value),
                    Err(e) => {
                        let _ = f.compare_exchange(
                            u32::MAX,
                            index,
                            Ordering::SeqCst,
                            Ordering::SeqCst,
                        );
                        Err(e)
                    }
                }
            }
        }
    };

    let values = each(scope, "units", None, 0..width, body).await?;
    Ok(values.into_iter().sum())
}

fn run_hex(dir: &std::path::Path) -> String {
    let text = dir.display().to_string();
    let mut hi: u64 = 0xcbf2_9ce4_8422_2325;
    for b in text.bytes() {
        hi ^= b as u64;
        hi = hi.wrapping_mul(0x0000_0100_0000_01b3);
    }
    let mut lo: u64 = 0x8422_2325_cbf2_9ce4;
    for b in text.bytes().rev() {
        lo ^= b as u64;
        lo = lo.wrapping_mul(0x0000_0100_0000_01b3);
    }
    if hi == 0 && lo == 0 {
        hi = 1;
    }
    format!("{:016x}{:016x}", hi, lo)
}

use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, within, FlowError, Scope};
use lgwks_bot::task::{task as declare_task, Disposition, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const RUN_HEX: &str = "0123456789abcdef0123456789abcdef";
const TENANT: &str = "recover";
const TASK_NAME: &str = "recover";
const UNITS_STEP: &str = "units";
const DEADLINE_STEP: &str = "deadline";
const EFFECT: &str = "recover";
const NO_INDEX: u32 = u32::MAX;

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let started = Instant::now();

    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;
    let failed = Arc::new(AtomicU32::new(NO_INDEX));

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let task_world = world.clone();
    let task_failed = failed.clone();

    let declared = declare_task(TASK_NAME, move |scope: Scope, _input: ()| {
        let world = task_world.clone();
        let failed = task_failed.clone();
        async move {
            let width = world.width();

            let work = each(
                &scope,
                UNITS_STEP,
                None,
                0..width,
                move |unit_scope, index| {
                    let world = world.clone();
                    let failed = failed.clone();
                    async move {
                        match world.unit(&unit_scope, index).await {
                            Ok(value) => Ok(value),
                            Err(_) => {
                                let _ = failed.compare_exchange(
                                    NO_INDEX,
                                    index,
                                    Ordering::SeqCst,
                                    Ordering::SeqCst,
                                );
                                Err(FlowError::failed(format!("unit {index}")))
                            }
                        }
                    }
                },
            );

            let remaining = deadline
                .checked_sub(started.elapsed())
                .unwrap_or(Duration::ZERO);
            let values = within(&scope, DEADLINE_STEP, remaining, work).await?;
            Ok(values.into_iter().sum::<u64>())
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &declared, ()).await;
    let disposition = report.disposition();
    let outcome = report.into_result();

    match outcome {
        Ok(total) => {
            let ledger = world.ledger();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        }
        Err(error) => {
            if matches!(disposition, Disposition::DeadlineExceeded)
                || error.is_cancelled()
                || matches!(
                    &error,
                    FlowError::TimedOut { .. } | FlowError::Cancelled { .. }
                )
            {
                Err(RecoveryError::Deadline)
            } else {
                let index = failed.load(Ordering::SeqCst);
                if index == NO_INDEX {
                    Err(RecoveryError::NoStore)
                } else {
                    Err(RecoveryError::Unit { index })
                }
            }
        }
    }
}

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, within, FlowError, Scope};
use lgwks_bot::task::{task as build_task, Disposition, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

struct CancelOnDrop<'a> {
    host: &'a Host,
    armed: bool,
}

impl Drop for CancelOnDrop<'_> {
    fn drop(&mut self) {
        if self.armed {
            self.host.cancel();
        }
    }
}

fn run_identity(store_dir: &Path, width: u32) -> Result<RunId, RecoveryError> {
    let mut hash: u128 = 0xcbf2_9ce4_8422_2325;
    let prime: u128 = 0x0000_0000_0000_0100_0000_0000_0000_013b;

    let text = store_dir.to_string_lossy();
    for byte in text.as_bytes() {
        hash ^= *byte as u128;
        hash = hash.wrapping_mul(prime);
    }
    for byte in width.to_le_bytes() {
        hash ^= byte as u128;
        hash = hash.wrapping_mul(prime);
    }

    if hash == 0 {
        hash = 1;
    }

    let hex = format!("{hash:032x}");
    RunId::from_hex(&hex).map_err(|_| RecoveryError::NoStore)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let width = world.width();
    let run = run_identity(store_dir.as_path(), width)?;

    let host = Host::builder("recovery")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(store_dir.as_path())
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let failed = Arc::new(AtomicI64::new(-1));

    let task = build_task("recover", {
        let task_failed = Arc::clone(&failed);
        move |scope: Scope, world: World| {
            let failed = Arc::clone(&task_failed);
            async move {
                let scope_ref = &scope;
                let units_world = world.clone();
                let units_failed = Arc::clone(&failed);
                let count = units_world.width();

                let total = within(
                    scope_ref,
                    "window",
                    deadline,
                    async move {
                        let values = each(
                            scope_ref,
                            "units",
                            None,
                            0..count,
                            move |item: Scope, index: u32| {
                                let world = units_world.clone();
                                let failed = Arc::clone(&units_failed);
                                async move {
                                    let value = world.unit(&item, index).await.map_err(|_| {
                                        failed.store(index as i64, Ordering::Relaxed);
                                        FlowError::failed("unit failed")
                                    })?;
                                    Ok::<u64, FlowError>(value)
                                }
                            },
                        )
                        .await?;
                        Ok::<u64, FlowError>(values.into_iter().sum())
                    },
                )
                .await?;

                let ledger = world.ledger();
                if !ledger.applied("recover") {
                    ledger.apply("recover");
                }

                Ok::<u64, FlowError>(total)
            }
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let mut guard = CancelOnDrop {
        host: &host,
        armed: true,
    };

    let report = host.resume(run, &task, world).await;
    let disposition = report.disposition();

    let result = match disposition {
        Disposition::Succeeded => match report.into_result() {
            Ok(total) => Ok(total),
            Err(_) => Err(RecoveryError::Unit { index: 0 }),
        },
        Disposition::DeadlineExceeded | Disposition::Cancelled | Disposition::Refused => {
            Err(RecoveryError::Deadline)
        }
        Disposition::Failed => {
            let index = failed.load(Ordering::Relaxed);
            if index >= 0 {
                Err(RecoveryError::Unit { index: index as u32 })
            } else if matches!(
                report.error(),
                Some(FlowError::TimedOut { .. }) | Some(FlowError::Cancelled { .. })
            ) {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::Unit { index: 0 })
            }
        }
        _ => Err(RecoveryError::Deadline),
    };

    guard.armed = false;
    result
}

use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};
use lgwks_bot::task::{task, Host};

const RUN_HEX: &str = "0123456789abcdef0123456789abcdef";
const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const EFFECT: &str = "recover";
const UNIT_STEP: &str = "units";
const GUARD_TENANT: &str = "recovery_guard";
const GUARD_STEP: &str = "guard";

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

static EFFECT_LOCK: Mutex<()> = Mutex::new(());

struct CancelOnDrop<'a> {
    host: &'a Host,
}

impl Drop for CancelOnDrop<'_> {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

fn record_failure(slot: &Mutex<Option<u32>>, index: u32) {
    let mut guard = match slot.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if guard.is_none() {
        *guard = Some(index);
    }
}

async fn run_units(
    world: World,
    scope: Scope,
    failed: Arc<Mutex<Option<u32>>>,
) -> Result<u64, FlowError> {
    let width = world.width();
    let values = each(
        &scope,
        UNIT_STEP,
        None,
        0..width,
        move |unit_scope: Scope, index: u32| {
            let world = world.clone();
            let failed = Arc::clone(&failed);
            async move {
                match world.unit(&unit_scope, index).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        record_failure(&failed, index);
                        Err(FlowError::failed(format!("unit {index} failed")))
                    }
                }
            }
        },
    )
    .await?;

    let mut total: u64 = 0;
    for value in values {
        total += value;
    }
    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let started = Instant::now();

    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(store_dir.as_path())
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let _cleanup = CancelOnDrop { host: &host };

    let failed = Arc::new(Mutex::new(None::<u32>));
    let job_world = world.clone();
    let job_failed = Arc::clone(&failed);
    let job = task(TASK_NAME, move |scope: Scope, _input: ()| {
        let world = job_world.clone();
        let failed = Arc::clone(&job_failed);
        async move { run_units(world, scope, failed).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let guard_tenant = Tenant::new(GUARD_TENANT).map_err(|_| RecoveryError::NoStore)?;
    let guard_scope = Scope::root(guard_tenant);

    let remaining = deadline.saturating_sub(started.elapsed());
    if remaining.is_zero() {
        host.cancel();
        return Err(RecoveryError::Deadline);
    }

    let raced = within(&guard_scope, GUARD_STEP, remaining, async {
        Ok::<_, FlowError>(host.resume(run, &job, ()).await)
    })
    .await;

    let report = match raced {
        Ok(report) => report,
        Err(_) => {
            host.cancel();
            return Err(RecoveryError::Deadline);
        }
    };

    if report.disposition().is_success() {
        let total = match report.output() {
            Some(value) => *value,
            None => {
                host.cancel();
                return Err(RecoveryError::Deadline);
            }
        };
        let _gate = match EFFECT_LOCK.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        let ledger = world.ledger();
        if !ledger.applied(EFFECT) {
            ledger.apply(EFFECT);
        }
        Ok(total)
    } else {
        host.cancel();
        let index = match failed.lock() {
            Ok(guard) => *guard,
            Err(poisoned) => *poisoned.into_inner(),
        };
        match index {
            Some(index) => Err(RecoveryError::Unit { index }),
            None => Err(RecoveryError::Deadline),
        }
    }
}

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope, Tenant};
use lgwks_bot::task::{task, Disposition, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TENANT: &str = "recovery";
const EFFECT: &str = "recover";

fn run_identity(dir: &Path) -> RunId {
    let mut low = DefaultHasher::new();
    dir.hash(&mut low);
    0u8.hash(&mut low);
    let low = low.finish();

    let mut high = DefaultHasher::new();
    dir.hash(&mut high);
    1u8.hash(&mut high);
    let high = high.finish();

    let mut hex = format!("{low:016x}{high:016x}");
    if hex.bytes().all(|b| b == b'0') {
        hex.pop();
        hex.push('1');
    }
    RunId::from_hex(&hex).expect("deterministic run id")
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = run_identity(&store_dir);

    let failure: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failure_in_job = failure.clone();
    let job_world = world.clone();

    let job = task("recover", move |scope: Scope, _input: ()| {
        let world = job_world.clone();
        let failure = failure_in_job.clone();
        async move {
            let values = script::each(&scope, "units", None, 0..world.width(), |step, index| {
                let world = world.clone();
                let failure = failure.clone();
                async move {
                    match world.unit(&step, index).await {
                        Ok(value) => Ok::<u64, FlowError>(value),
                        Err(_) => {
                            if let Ok(mut slot) = failure.lock() {
                                *slot = Some(index);
                            }
                            Err(FlowError::failed("unit failed"))
                        }
                    }
                }
            })
            .await?;

            Ok::<u64, FlowError>(values.into_iter().sum())
        }
    })
    .map_err(|_| RecoveryError::NoLedger)?;

    let root = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoLedger)?);

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoLedger)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let outcome = script::within(&root, EFFECT, deadline, async {
        Ok::<_, FlowError>(host.resume::<(), u64, _, _>(run, &job, ()).await)
    })
    .await;

    let report = match outcome {
        Ok(report) => report,
        Err(_) => return Err(RecoveryError::Deadline),
    };

    let disposition = report.disposition();

    match report.into_result() {
        Ok(total) => {
            let ledger = world.ledger();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        }
        Err(_) => {
            if matches!(disposition, Disposition::DeadlineExceeded | Disposition::Cancelled) {
                return Err(RecoveryError::Deadline);
            }
            let index = match failure.lock() {
                Ok(slot) => (*slot).unwrap_or(0),
                Err(_) => 0,
            };
            Err(RecoveryError::Unit { index })
        }
    }
}

use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, within};
use lgwks_bot::task::{self, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

fn run_hex(dir: &Path) -> String {
    let mut a: u64 = 0xcbf2_9ce4_8422_2325;
    let mut b: u64 = 0x8422_2325_cbf2_9ce4;
    for byte in dir.to_string_lossy().bytes() {
        a ^= byte as u64;
        a = a.wrapping_mul(0x0000_0100_0000_01b3);
        b = b.rotate_left(7) ^ a;
        b = b.wrapping_mul(0x0000_0100_0000_01b3);
    }
    if a == 0 && b == 0 {
        b = 1;
    }
    format!("{:016x}{:016x}", a, b)
}

async fn complete(
    world: &World,
    scope: &Scope,
    deadline: Duration,
    fail: &Mutex<Option<RecoveryError>>,
) -> Result<u64, FlowError> {
    let body = async {
        let mut total: u64 = 0;
        let mut index: u32 = 0;
        while index < world.width() {
            match world.unit(scope, index).await {
                Ok(value) => total = total.wrapping_add(value),
                Err(_) => {
                    *fail.lock().unwrap() = Some(RecoveryError::Unit { index });
                    return Err(FlowError::failed("a unit failed"));
                }
            }
            index += 1;
        }
        let ledger = world.ledger();
        if !ledger.applied("recover") {
            ledger.apply("recover");
        }
        Ok(total)
    };
    within(scope, "recover", deadline, body).await
}

pub async fn recover(
    world: World,
    store_dir: std::path::PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(&run_hex(&store_dir)).map_err(|_| RecoveryError::NoLedger)?;
    let host = Host::builder("recovery")
        .map_err(|_| RecoveryError::NoLedger)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoLedger)?;

    let fail: Arc<Mutex<Option<RecoveryError>>> = Arc::new(Mutex::new(None));
    let fail_in = Arc::clone(&fail);
    let job = task::task("recover", move |scope: Scope, world: World| {
        let fail = Arc::clone(&fail_in);
        async move { complete(&world, &scope, deadline, &fail).await }
    })
    .map_err(|_| RecoveryError::NoLedger)?;

    let report = host.resume(run, &job, world).await;
    match report.into_result() {
        Ok(total) => Ok(total),
        Err(_) => match fail.lock().unwrap().take() {
            Some(error) => Err(error),
            None => Err(RecoveryError::Deadline),
        },
    }
}

use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{remember, within, FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host};

const RUN_HEX: &str = "0123456789abcdef0123456789abcdef";
const EFFECT: &str = "recover";
const NO_INDEX: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let host = Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let failed = Arc::new(AtomicU32::new(NO_INDEX));
    let world_for_task = world.clone();
    let failed_for_task = failed.clone();

    let task = task("recover", move |scope: Scope, _input: ()| {
        let world = world_for_task.clone();
        let failed = failed_for_task.clone();
        async move { drive(world, scope, deadline, failed).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &task, ()).await;

    match report.disposition() {
        Disposition::Succeeded => {
            let total = report.into_result().map_err(|_| RecoveryError::Deadline)?;
            let ledger = world.ledger();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        }
        Disposition::DeadlineExceeded | Disposition::Cancelled => Err(RecoveryError::Deadline),
        Disposition::Refused => Err(RecoveryError::NoStore),
        Disposition::Failed => {
            let timed = match report.error() {
                Some(err) => err.is_cancelled() || matches!(err, FlowError::TimedOut { .. }),
                None => false,
            };
            if timed {
                return Err(RecoveryError::Deadline);
            }
            let index = failed.load(Ordering::SeqCst);
            if index == NO_INDEX {
                Err(RecoveryError::NoStore)
            } else {
                Err(RecoveryError::Unit { index })
            }
        }
    }
}

async fn drive(
    world: World,
    scope: Scope,
    deadline: Duration,
    failed: Arc<AtomicU32>,
) -> Result<u64, FlowError> {
    within(
        &scope,
        "recover",
        deadline,
        run_units(&world, &scope, failed.as_ref()),
    )
    .await
}

async fn one_unit(world: &World, scope: &Scope, index: u32) -> Result<u64, FlowError> {
    world
        .unit(scope, index)
        .await
        .map_err(|_| FlowError::failed("unit failed"))
}

async fn run_units(world: &World, scope: &Scope, failed: &AtomicU32) -> Result<u64, FlowError> {
    let width = world.width();
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    while index < width {
        let step = format!("author-unit-{index}");
        let outcome = remember(scope, &step, || one_unit(world, scope, index)).await;
        match outcome {
            Ok(value) => {
                total = total.wrapping_add(value);
                index += 1;
            }
            Err(err) => {
                if !err.is_cancelled() && !matches!(err, FlowError::TimedOut { .. }) {
                    failed.store(index, Ordering::SeqCst);
                }
                return Err(err);
            }
        }
    }
    Ok(total)
}

use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, remember, within, FlowError, Scope, Tenant};
use lgwks_bot::task::{task, Disposition, Host};

const RUN_HEX: &str = "00000000000000000000000000000001";
const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const EFFECT: &str = "recover";

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoLedger)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let work = {
        let task_world = world.clone();
        let task_failed = Arc::clone(&failed);
        task(TASK_NAME, move |scope: Scope, _: ()| {
            let world = task_world.clone();
            let failed = task_failed.clone();
            async move {
                let width = world.width();
                let values = each(&scope, "units", None, 0..width, |unit_scope, index| {
                    let world = world.clone();
                    let failed = failed.clone();
                    async move {
                        let step = format!("recover-unit-{}", index);
                        let outcome: Result<u64, FlowError> =
                            remember(&unit_scope, &step, || async {
                                match world.unit(&unit_scope, index).await {
                                    Ok(value) => Ok(value),
                                    Err(_) => Err(FlowError::failed("unit failed")),
                                }
                            })
                            .await;
                        match outcome {
                            Ok(value) => Ok(value),
                            Err(err) => {
                                if !err.is_cancelled() {
                                    let mut slot = failed.lock().unwrap();
                                    if slot.is_none() {
                                        *slot = Some(index);
                                    }
                                }
                                Err(err)
                            }
                        }
                    }
                })
                .await?;
                Ok::<u64, FlowError>(values.into_iter().sum())
            }
        })
        .map_err(|_| RecoveryError::NoLedger)?
    };

    let timer = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoLedger)?);

    let raced = within(&timer, TASK_NAME, deadline, async {
        Ok::<_, FlowError>(host.resume(run, &work, ()).await)
    })
    .await;

    let report = match raced {
        Ok(report) => report,
        Err(_) => {
            host.cancel();
            return Err(RecoveryError::Deadline);
        }
    };

    match report.disposition() {
        Disposition::Succeeded => {}
        Disposition::Failed => {
            let index = *failed.lock().unwrap();
            return Err(match index {
                Some(index) => RecoveryError::Unit { index },
                None => RecoveryError::NoStore,
            });
        }
        Disposition::DeadlineExceeded | Disposition::Cancelled => {
            host.cancel();
            return Err(RecoveryError::Deadline);
        }
        _ => return Err(RecoveryError::NoStore),
    }

    let total = report.into_result().map_err(|_| RecoveryError::NoStore)?;

    let ledger = world.ledger();
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }

    Ok(total)
}

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{within, FlowError, Scope, Tenant};
use lgwks_bot::task::{self, Host, Report};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TENANT: &str = "recover";
const TASK_NAME: &str = "recover";
const DEADLINE_STEP: &str = "deadline";
const EFFECT: &str = "recover";

struct CancelOnDrop<'a>(&'a Host);

impl<'a> Drop for CancelOnDrop<'a> {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

fn deterministic_run(store_dir: &std::path::Path) -> RunId {
    let mut first = DefaultHasher::new();
    store_dir.hash(&mut first);
    let high = first.finish();

    let mut second = DefaultHasher::new();
    high.hash(&mut second);
    let low = (second.finish() ^ 0x9e37_79b9_7f4a_7c15) | 1;

    let text = format!("{:016x}{:016x}", high, low);
    RunId::from_hex(&text).expect("thirty-two lowercase hex characters")
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = deterministic_run(&store_dir);

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let _cancel = CancelOnDrop(&host);

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_in_body = failed.clone();

    let task = task::task(TASK_NAME, move |scope: Scope, world: World| {
        let failed = failed_in_body.clone();
        async move {
            let width = world.width();
            let mut total: u64 = 0;
            let mut index: u32 = 0;
            while index < width {
                match world.unit(&scope, index).await {
                    Ok(value) => total = total.wrapping_add(value),
                    Err(_) => {
                        if let Ok(mut slot) = failed.lock() {
                            *slot = Some(index);
                        }
                        return Err(FlowError::failed(format!("unit {index}")));
                    }
                }
                index += 1;
            }
            Ok(total)
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let tenant = Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let scope = Scope::root(tenant);

    let outcome = within(&scope, DEADLINE_STEP, deadline, async {
        let report = host.resume(run, &task, world.clone()).await;
        Ok::<Report<u64>, FlowError>(report)
    })
    .await;

    let report = match outcome {
        Ok(report) => report,
        Err(_) => return Err(RecoveryError::Deadline),
    };

    if report.disposition().is_success() {
        let total = match report.into_result() {
            Ok(total) => total,
            Err(_) => return Err(RecoveryError::Deadline),
        };

        let ledger = world.ledger();
        if !ledger.applied(EFFECT) {
            ledger.apply(EFFECT);
        }

        return Ok(total);
    }

    match failed.lock().ok().and_then(|mut slot| slot.take()) {
        Some(index) => Err(RecoveryError::Unit { index }),
        None => Err(RecoveryError::Deadline),
    }
}

use std::path::Path;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{each, remember, within, FlowError, Scope, Tenant};
use lgwks_bot::task::{task, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

trait LedgerRef<'a, T> {
    fn ledger_ref(self) -> Option<&'a T>;
}

impl<'a, T> LedgerRef<'a, T> for &'a T {
    fn ledger_ref(self) -> Option<&'a T> {
        Some(self)
    }
}

impl<'a, T> LedgerRef<'a, T> for Option<&'a T> {
    fn ledger_ref(self) -> Option<&'a T> {
        self
    }
}

impl<'a, T, E> LedgerRef<'a, T> for Result<&'a T, E> {
    fn ledger_ref(self) -> Option<&'a T> {
        self.ok()
    }
}

struct CancelOnDrop<'a> {
    host: &'a Host,
}

impl Drop for CancelOnDrop<'_> {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

fn derive_run_id(store_dir: &Path) -> RunId {
    let key = store_dir.to_string_lossy();
    let mut h1: u64 = 0xcbf2_9ce4_8422_2325;
    let mut h2: u64 = 0x9e37_79b9_7f4a_7c15;
    for byte in key.bytes() {
        h1 ^= u64::from(byte);
        h1 = h1.wrapping_mul(0x0000_0100_0000_01b3);
        h2 ^= h1;
        h2 = h2.rotate_left(17).wrapping_mul(0x0000_0100_0000_01b3);
    }
    let hex = format!("{h1:016x}{h2:016x}");
    RunId::from_hex(&hex)
        .unwrap_or_else(|_| RunId::from_hex("00000000000000000000000000000001").expect("valid"))
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let run = derive_run_id(&store_dir);
    let tenant = Tenant::new("recover").map_err(|_| RecoveryError::NoStore)?;
    let scope = Scope::root(tenant);

    let host = Host::builder("recover")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let _cancel = CancelOnDrop { host: &host };

    let failing = Arc::new(AtomicU32::new(0));
    let task_world = world.clone();
    let task_failing = Arc::clone(&failing);

    let work = task("recover", move |task_scope: Scope, _input: ()| {
        let world = task_world.clone();
        let failing = Arc::clone(&task_failing);
        async move {
            let width = world.width();
            let values = each(
                &task_scope,
                "units",
                None,
                0..width,
                move |unit_scope: Scope, index: u32| {
                    let world = world.clone();
                    let failing = Arc::clone(&failing);
                    async move {
                        let step = format!("recover_unit_{index}");
                        let scope_ref: &Scope = &unit_scope;
                        let world_ref: &World = &world;
                        let record = remember(&unit_scope, &step, move || async move {
                            world_ref
                                .unit(scope_ref, index)
                                .await
                                .map_err(|_| FlowError::failed(format!("unit:{index}")))
                        })
                        .await;
                        match record {
                            Ok(value) => Ok(value),
                            Err(error) => {
                                failing.store(index.saturating_add(1), Ordering::SeqCst);
                                Err(error)
                            }
                        }
                    }
                },
            )
            .await?;
            let total: u64 = values.into_iter().sum();
            Ok(total)
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let attempt = async {
        let report = host.resume(run, &work, ()).await;
        report.into_result()
    };

    match within(&scope, "recover_deadline", deadline, attempt).await {
        Ok(total) => {
            let ledger = world
                .ledger()
                .ledger_ref()
                .ok_or(RecoveryError::NoLedger)?;
            if !ledger.applied("recover") {
                ledger.apply("recover");
            }
            Ok(total)
        }
        Err(_) => {
            let marker = failing.load(Ordering::SeqCst);
            if marker == 0 {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::Unit { index: marker - 1 })
            }
        }
    }
}

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::UnitError;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope, Tenant};
use lgwks_bot::task::{self, Host};

const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const UNITS_STEP: &str = "units";
const ATTEMPT_STEP: &str = "attempt";
const EFFECT_STEP: &str = "effect";
const EFFECT_NAME: &str = "recover";
const FANOUT: usize = 8;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// A private carrier for a unit failure that is passed on to `FlowError`.
#[derive(Debug)]
struct UnitFailed {
    index: u32,
    detail: String,
}

impl UnitFailed {
    fn new(index: u32) -> Self {
        Self {
            index,
            detail: format!("unit {} failed", index),
        }
    }
}

impl std::fmt::Display for UnitFailed {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.detail)
    }
}

impl std::error::Error for UnitFailed {}

impl From<UnitFailed> for String {
    fn from(value: UnitFailed) -> String {
        value.detail
    }
}

impl From<UnitFailed> for std::borrow::Cow<'static, str> {
    fn from(value: UnitFailed) -> Self {
        std::borrow::Cow::Owned(value.detail)
    }
}

/// A run identity derived from where the store lives, so every attempt at the
/// same `store_dir` addresses the same run and finds the earlier records.
fn run_hex(dir: &Path, width: u32) -> String {
    let mut seed: Vec<u8> = dir.to_string_lossy().into_owned().into_bytes();
    seed.push(0x1f);
    seed.extend_from_slice(&width.to_le_bytes());

    let mut lo: u64 = 0xcbf2_9ce4_8422_2325;
    let mut hi: u64 = 0x9ae1_6a3b_2f90_404f;
    for byte in seed {
        lo ^= u64::from(byte);
        lo = lo.wrapping_mul(0x0000_0100_0000_01b3);
        hi = hi.rotate_left(7) ^ u64::from(byte).wrapping_mul(0xff51_afd7_ed55_8ccd);
        hi = hi.wrapping_mul(0x0000_0100_0000_01b3);
    }
    if lo == 0 && hi == 0 {
        lo = 1;
    }
    format!("{:016x}{:016x}", lo, hi)
}

fn note(failure: &Arc<Mutex<Option<u32>>>, index: u32) {
    if let Ok(mut slot) = failure.lock() {
        *slot = Some(index);
    }
}

fn classify(err: &FlowError, failure: &Arc<Mutex<Option<u32>>>) -> RecoveryError {
    match err {
        FlowError::TimedOut { .. } => RecoveryError::Deadline,
        _ => failure
            .lock()
            .ok()
            .and_then(|slot| *slot)
            .map(|index| RecoveryError::Unit { index })
            .unwrap_or(RecoveryError::NoLedger),
    }
}

/// The task body: drive every unit, then apply the effect exactly once. Built
/// once per `recover` call and used by whichever attempt the host runs.
async fn run_attempt(
    world: ai_task_support::recovery::World,
    failure: Arc<Mutex<Option<u32>>>,
    scope: Scope,
) -> Result<u64, FlowError> {
    let width = world.width();
    let limit = script::at_most(FANOUT)?;

    let for_units = world.clone();
    let values: Vec<u64> = script::each(
        &scope,
        UNITS_STEP,
        Some(limit),
        0u32..width,
        move |item: Scope, index: u32| {
            let world = for_units.clone();
            let failure = failure.clone();
            async move {
                match world.unit(&item, index).await {
                    Ok(value) => Ok(value),
                    Err(UnitError::Unit { index }) => {
                        note(&failure, index);
                        Err(FlowError::failed(UnitFailed::new(index)))
                    }
                }
            }
        },
    )
    .await?;

    let total: u64 = values.into_iter().sum();

    // The effect is guarded twice: the record keeps the body from running on a
    // later attempt, and the ledger's own view covers a lost record.
    script::remember::<u64, _>(&scope, EFFECT_STEP, move || async move {
        let ledger = world.ledger();
        if !ledger.applied(EFFECT_NAME) {
            ledger.apply(EFFECT_NAME);
        }
        Ok::<u64, FlowError>(0)
    })
    .await?;

    Ok(total)
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    std::fs::create_dir_all(&store_dir).map_err(|_| RecoveryError::NoStore)?;

    let key = std::fs::canonicalize(&store_dir).unwrap_or_else(|_| store_dir.clone());
    let run = RunId::from_hex(&run_hex(&key, world.width())).map_err(|_| RecoveryError::NoStore)?;

    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder.run_store(&store_dir).map_err(|_| RecoveryError::NoStore)?;
    let host = builder
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let failure: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let task = task::task(TASK_NAME, {
        let world = world.clone();
        let failure = failure.clone();
        move |scope: Scope, _input: ()| {
            let world = world.clone();
            let failure = failure.clone();
            async move { run_attempt(world, failure, scope).await }
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let root = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?);

    let report = match script::within(&root, ATTEMPT_STEP, deadline, async move {
        let report = host.resume(run, &task, ()).await;
        Ok::<lgwks_bot::task::Report<u64>, FlowError>(report)
    })
    .await
    {
        Ok(report) => report,
        Err(err) => return Err(classify(&err, &failure)),
    };

    if let Some(err) = report.error() {
        return Err(classify(err, &failure));
    }

    report.output().copied().ok_or(RecoveryError::NoLedger)
}

//! Resumable recovery over `ai_task_support::recovery` worlds.

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, at_most, each, remember, within};
use lgwks_bot::task::{Host, task};

/// The effect is applied under this name, exactly once across all attempts.
const EFFECT: &str = "recover";
/// Name of the durable task.
const TASK_NAME: &str = "recover";
/// Tenant that owns the durable run store.
const TENANT: &str = "recovery";
/// Fan-out bound for the unit bodies.
const UNITS: usize = 8;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Recover the whole world under one durable run identity.
///
/// The run identity is derived from `store_dir`, so it is identical on every
/// call: the first attempt records each finished unit durably, and every later
/// attempt resumes the same run, replaying those records instead of re-running
/// the bodies behind them.
pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    if deadline.is_zero() {
        return Err(RecoveryError::Deadline);
    }

    let run = run_identity(&store_dir)?;
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    // The body is built once here and is what every attempt against this run
    // executes; a resumed attempt replays its records rather than redoing it.
    let owned = world.clone();
    let watch = Arc::clone(&failed);
    let job = task(TASK_NAME, move |scope: Scope, _input: ()| {
        let world = owned.clone();
        let failed = Arc::clone(&watch);
        async move {
            within(&scope, "recover", deadline, drive(&scope, &world, &failed)).await
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    match host.resume(run, &job, ()).await.into_result() {
        Ok(total) => {
            if world.ledger().applies() == 1 {
                Ok(total)
            } else {
                Err(RecoveryError::NoLedger)
            }
        }
        Err(error) => Err(classify(&error, &failed)),
    }
}

/// Apply the effect once, then fan out over every unit of the world.
async fn drive(
    scope: &Scope,
    world: &World,
    failed: &Arc<Mutex<Option<u32>>>,
) -> Result<u64, FlowError> {
    // Guarded by `applied` as well as by the record: if a previous attempt was
    // killed between applying and recording, the replay must not apply again.
    let effect = world.clone();
    let _applied = remember(scope, "effect", move || async move {
        if !effect.ledger().applied(EFFECT) {
            effect.ledger().apply(EFFECT);
        }
        Ok::<u64, FlowError>(0u64)
    })
    .await?;

    let pool = Some(at_most(UNITS)?);
    let owner = world.clone();
    let watch = Arc::clone(failed);
    let values: Vec<u64> = each(scope, "units", pool, 0..owner.width(), move |item, index| {
        let world = owner.clone();
        let failed = Arc::clone(&watch);
        async move { unit(&item, &world, &failed, index).await }
    })
    .await?;

    Ok(values.into_iter().sum())
}

/// One unit. The unit records its own value durably, so a resumed run replays
/// it without running the body again.
async fn unit(
    scope: &Scope,
    world: &World,
    failed: &Arc<Mutex<Option<u32>>>,
    index: u32,
) -> Result<u64, FlowError> {
    match world.unit(scope, index).await {
        Ok(value) => Ok(value),
        Err(UnitError::Unit { index }) => {
            note(failed, index);
            Err(FlowError::failed("unit failed"))
        }
        Err(_) => Err(FlowError::transient("unit failed")),
    }
}

fn note(failed: &Arc<Mutex<Option<u32>>>, index: u32) {
    if let Ok(mut slot) = failed.lock() {
        if slot.is_none() {
            *slot = Some(index);
        }
    }
}

fn classify(error: &FlowError, failed: &Arc<Mutex<Option<u32>>>) -> RecoveryError {
    if error.is_cancelled() {
        return RecoveryError::Deadline;
    }
    if let FlowError::TimedOut { .. } = error {
        return RecoveryError::Deadline;
    }
    if let Ok(slot) = failed.lock() {
        if let Some(index) = *slot {
            return RecoveryError::Unit { index };
        }
    }
    RecoveryError::NoLedger
}

/// A run identity that is stable across attempts: derived from the store
/// directory, so the same directory always resumes the same run, and two
/// different directories never share records.
fn run_identity(dir: &Path) -> Result<RunId, RecoveryError> {
    use std::hash::{Hash, Hasher};

    let mut first = std::collections::hash_map::DefaultHasher::new();
    dir.to_string_lossy().hash(&mut first);
    let head = first.finish();

    let mut second = std::collections::hash_map::DefaultHasher::new();
    head.hash(&mut second);
    b"lgwks.recover".hash(&mut second);
    let tail = second.finish();

    let tail = if head == 0 && tail == 0 { 1 } else { tail };
    RunId::from_hex(&format!("{head:016x}{tail:016x}")).map_err(|_| RecoveryError::NoStore)
}

#![forbid(unsafe_code)]

//! Recovery over an `ai_task_support::recovery::World`.
//!
//! Every attempt rebuilds the same task under the same [`RunId`], derived from
//! the durable store directory rather than from fresh randomness, so a second
//! attempt replays the records the first one committed instead of re-running
//! the unit bodies behind them. The single ledger effect is guarded by a read
//! of `applied` before it is applied, so it lands exactly once across attempts.
//! Every resource started here — the attempt, the host that owns the store — is
//! stopped explicitly on the way out, including when the caller drops the
//! returned future mid-run.

use std::fmt;
use std::future::Future;
use std::path::{Path, PathBuf};
use std::pin::Pin;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{at_most, each, within, FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host, Task};

/// The one ledger effect, applied exactly once across every attempt.
const EFFECT: &str = "recover";
/// The tenant that owns the durable store.
const TENANT: &str = "recover";
/// The name of the single task every attempt runs.
const TASK_NAME: &str = "recover";
/// The step the whole fan-out runs under.
const WORK_STEP: &str = "work";
/// The step the unit fan-out runs under.
const UNITS_STEP: &str = "units";
/// How many unit bodies may be live at once.
const FAN_OUT: usize = 4;
/// Sentinel in the failed-unit slot: no unit has reported a failure.
const NO_UNIT: u32 = u32::MAX;
/// Progress slots beyond the per-unit ones.
const PROGRESS_SLACK: usize = 64;

/// The task body. Built once per attempt, but the *same* body — and the same
/// run under it — is what makes a resume replay instead of re-run.
type Body = Pin<Box<dyn Future<Output = Result<u64, FlowError>> + 'static>>;
type TaskBody = Box<dyn Fn(Scope, ()) -> Body + Send + 'static>;

/// Why a recovery attempt did not produce a total.
#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

impl fmt::Display for RecoveryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            RecoveryError::Unit { index } => write!(f, "unit {index} failed"),
            RecoveryError::Deadline => f.write_str("the recovery deadline elapsed"),
            RecoveryError::NoStore => f.write_str("no durable run store is available"),
            RecoveryError::NoLedger => f.write_str("the ledger effect was not applied"),
        }
    }
}

impl std::error::Error for RecoveryError {}

/// Owns one attempt: cancelling the host tears down anything still live, and
/// dropping it releases the store. The guard holds the host and the task for
/// the whole attempt — including while the attempt is running — so the path
/// where the caller drops the future returned by [`recover`] still cancels and
/// releases, rather than dropping a live host on the floor.
struct Attempt {
    run: RunId,
    world: World,
    /// Index of the unit that failed, or [`NO_UNIT`].
    failed: Arc<AtomicU32>,
    host: Option<Host>,
    task: Option<Task<TaskBody>>,
}

impl Attempt {
    /// Opens the store, derives the run identity and builds the task body.
    fn new(world: &World, store_dir: &Path, deadline: Duration) -> Result<Self, RecoveryError> {
        let width = world.width();
        let host = open(store_dir, width, deadline)?;
        // The store now exists, so the path can be canonicalised: the identity
        // is derived from the store's location, which is stable across attempts.
        let run = run_id(store_dir, width)?;

        let limit = at_most(FAN_OUT).map_err(|_| RecoveryError::NoStore)?;
        let failed = Arc::new(AtomicU32::new(NO_UNIT));
        let source = world.clone();

        let body: TaskBody = Box::new(move |scope: Scope, _input: ()| -> Body {
            let world = source.clone();
            let failed = Arc::clone(&failed);
            Box::pin(async move {
                // Raced against the deadline and against cancellation, so a
                // body still live when the limit passes is dropped with it and
                // no further unit is started.
                let values: Vec<u64> = within(
                    &scope,
                    WORK_STEP,
                    deadline,
                    each(
                        &scope,
                        UNITS_STEP,
                        Some(limit),
                        0..world.width(),
                        move |step: Scope, index: u32| {
                            let world = world.clone();
                            let failed = Arc::clone(&failed);
                            async move {
                                match world.unit(&step, index).await {
                                    Ok(value) => Ok(value),
                                    Err(_) => {
                                        failed.store(index, Ordering::SeqCst);
                                        Err(FlowError::failed("the unit body failed"))
                                    }
                                }
                            }
                        },
                    ),
                )
                .await?;

                Ok::<u64, FlowError>(values.into_iter().sum())
            })
        });

        let handle = task(TASK_NAME, body).map_err(|_| RecoveryError::NoStore)?;

        Ok(Attempt {
            run,
            world: world.clone(),
            failed,
            host: Some(host),
            task: Some(handle),
        })
    }

    /// Runs the attempt to a verdict, then stops it before returning.
    async fn run(mut self) -> Result<u64, RecoveryError> {
        if self.host.is_none() || self.task.is_none() {
            self.stop();
            return Err(RecoveryError::NoStore);
        }

        let run = self.run;
        let (disposition, outcome, failed_unit) = {
            let host = self.host.as_ref().expect("armed by new");
            let handle = self.task.as_ref().expect("armed by new");
            // Every attempt — the first and every resume — runs this very task
            // under this very run id, so a recorded unit replays.
            let report = host.resume(run, handle, ()).await;
            // Read the verdict before the attempt is torn down.
            let disposition = report.disposition();
            let failed_unit = self.failed.load(Ordering::SeqCst);
            (disposition, report.into_result(), failed_unit)
        };

        // Cancels anything the attempt left live, then releases the store.
        self.stop();

        match outcome {
            Ok(total) => {
                apply_effect(&self.world)?;
                Ok(total)
            }
            Err(err) => Err(classify(&err, failed_unit, disposition)),
        }
    }

    /// Cancels the host, then releases the task and the host it owns.
    fn stop(&mut self) {
        if let Some(host) = self.host.as_ref() {
            host.cancel();
        }
        if let Some(handle) = self.task.take() {
            drop(handle);
        }
        if let Some(host) = self.host.take() {
            drop(host);
        }
    }
}

impl Drop for Attempt {
    fn drop(&mut self) {
        self.stop();
    }
}

/// Runs every unit of `world` exactly once, resuming whatever an earlier,
/// interrupted attempt already recorded, and resolves with the sum of the unit
/// values once all of them have completed.
pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    Attempt::new(&world, &store_dir, deadline)?.run().await
}

/// Opens the durable store and builds the host that owns it.
fn open(store_dir: &Path, width: u32, deadline: Duration) -> Result<Host, RecoveryError> {
    let concurrency = at_most(1).map_err(|_| RecoveryError::NoStore)?;
    Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .max_concurrent_tasks(concurrency)
        .default_deadline(deadline)
        .progress_capacity(width as usize * 2 + PROGRESS_SLACK)
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)
}

/// The run identity: derived from the store's location, so it is stable for a
/// given store — the second call finds the first call's records — and different
/// for a different one. No fresh randomness per call. Always 32 lowercase hex
/// characters, never all zero.
fn run_id(store_dir: &Path, width: u32) -> Result<RunId, RecoveryError> {
    let path = std::fs::canonicalize(store_dir).unwrap_or_else(|_| store_dir.to_path_buf());
    let mut material = Vec::new();
    material.extend_from_slice(TENANT.as_bytes());
    material.push(0);
    material.extend_from_slice(&width.to_le_bytes());
    material.push(0);
    material.extend_from_slice(path.to_string_lossy().as_bytes());

    let hi = fnv1a(&material, 0xcbf2_9ce4_8422_2325);
    let lo = fnv1a(&material, 0x8422_2325_cbf2_9ce4);
    let (hi, lo) = if hi == 0 && lo == 0 { (1, 0) } else { (hi, lo) };

    RunId::from_hex(&format!("{hi:016x}{lo:016x}")).map_err(|_| RecoveryError::NoStore)
}

const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

fn fnv1a(bytes: &[u8], offset: u64) -> u64 {
    let mut hash = offset;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    hash
}

/// Applies the ledger effect, but only if no attempt has applied it before:
/// reading `applied` is the only deduplication on offer, and it is what keeps
/// the effect at exactly one application across the first attempt and every
/// resume.
fn apply_effect(world: &World) -> Result<(), RecoveryError> {
    let ledger = world.ledger();
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }
    if !ledger.applied(EFFECT) {
        return Err(RecoveryError::NoLedger);
    }
    Ok(())
}

/// Maps a located flow error onto the recovery surface. A cancelled or
/// timed-out attempt is a deadline; a unit that named itself is a unit failure;
/// anything else left the durable run unusable.
fn classify(err: &FlowError, failed: u32, disposition: Disposition) -> RecoveryError {
    if err.is_cancelled() {
        return RecoveryError::Deadline;
    }
    match disposition {
        Disposition::DeadlineExceeded | Disposition::Cancelled => RecoveryError::Deadline,
        _ => match failed {
            NO_UNIT => RecoveryError::NoStore,
            index => RecoveryError::Unit { index },
        },
    }
}

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{self, UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{within, FlowError, Scope, Tenant};
use lgwks_bot::task::{task, Disposition, Host, Report};

const TENANT: &str = "recover";
const TASK_NAME: &str = "recover.units";
const DEADLINE_STEP: &str = "deadline";
const EFFECT: &str = "recover";
const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
const SEED: u64 = 0x9e37_79b9_7f4a_7c15;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// What the task body reports back to the caller of `recover`: which unit
/// failed, if any, and whether the loop actually reached the end of the world.
#[derive(Default)]
struct Progress {
    failed: Option<u32>,
    finished: bool,
}

type Shared = Arc<Mutex<Progress>>;

/// The task input. The world travels as data rather than as a capture, so the
/// very same task body can be handed to the first attempt and to every resume.
type Input = (World, Shared);

/// Cancels the host if the future driving it goes away. Every unit body is
/// owned by the host's task, so the host is the only thing that can guarantee
/// nothing stays live once this guard is dropped mid-flight.
struct CancelOnDrop<'a> {
    host: &'a Host,
    armed: bool,
}

impl Drop for CancelOnDrop<'_> {
    fn drop(&mut self) {
        if self.armed {
            self.host.cancel();
        }
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    // The run identity has to be the same on every attempt, so it is derived
    // from the store itself rather than drawn afresh per call.
    let run = run_id(&store_dir)?;
    let host = build_host(&store_dir, deadline)?;
    let scope = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?);
    let units = task(TASK_NAME, run_units).map_err(|_| RecoveryError::NoStore)?;
    let progress: Shared = Arc::new(Mutex::new(Progress::default()));

    // Armed for the whole call: if this future is dropped, the host is
    // cancelled and every body it owns counts out.
    let mut guard = CancelOnDrop {
        host: &host,
        armed: true,
    };

    let attempt = host.resume(run, &units, (world.clone(), progress.clone()));
    let outcome = match within(&scope, DEADLINE_STEP, deadline, attempt).await {
        Ok(report) => classify(&report, &progress),
        Err(err) => {
            // The attempt was abandoned: stop the fan-out before returning.
            host.cancel();
            match failed_index(&progress) {
                Some(index) => Err(RecoveryError::Unit { index }),
                None if is_time(&err) => Err(RecoveryError::Deadline),
                None => Err(RecoveryError::NoStore),
            }
        }
    };

    // The run is accounted for; an ordinary return must not cancel the host.
    guard.armed = false;

    match outcome {
        Ok(total) => {
            // Reading first is the only deduplication the ledger offers, so the
            // effect lands exactly once across any number of attempts.
            let ledger = world.ledger();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        }
        Err(err) => Err(err),
    }
}

/// The task body, built once and reused by the first attempt and by every
/// resume. A unit that already recorded under `unit_step(index)` replays its
/// value here without its body running again.
async fn run_units(scope: Scope, input: Input) -> Result<u64, FlowError> {
    let (world, progress) = input;
    let mut total: u64 = 0;
    let mut failed: Option<u32> = None;
    let mut finished = true;

    for index in 0..world.width() {
        if scope.is_cancelled() {
            finished = false;
            break;
        }
        let step = match scope.enter(&recovery::unit_step(index)) {
            Ok(step) => step,
            Err(_) => {
                failed = Some(index);
                finished = false;
                break;
            }
        };
        match world.unit(&step, index).await {
            Ok(value) => total = total.saturating_add(value),
            Err(err) => {
                // A cancellation does not name a unit; only `Unit` does.
                failed = unit_index(&err);
                finished = false;
                break;
            }
        }
    }

    if let Ok(mut slot) = progress.lock() {
        if slot.failed.is_none() {
            slot.failed = failed;
        }
        slot.finished = finished;
    }

    Ok(total)
}

/// Builds the host with the durable run store installed. A host that refuses
/// the requested default deadline is retried without one: the overall deadline
/// is enforced by `within` either way.
fn build_host(store_dir: &Path, deadline: Duration) -> Result<Host, RecoveryError> {
    match install(store_dir, Some(deadline)) {
        Ok(host) => Ok(host),
        Err(_) => install(store_dir, None),
    }
}

fn install(store_dir: &Path, deadline: Option<Duration>) -> Result<Host, RecoveryError> {
    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = match deadline {
        Some(limit) => builder.default_deadline(limit),
        None => builder,
    };
    builder
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)
}

fn classify(report: &Report<u64>, progress: &Shared) -> Result<u64, RecoveryError> {
    let index = failed_index(progress);
    match report.disposition() {
        Disposition::Succeeded => {
            if let Some(index) = index {
                return Err(RecoveryError::Unit { index });
            }
            if !is_finished(progress) {
                // Reported success without reaching the end of the world.
                return Err(RecoveryError::Deadline);
            }
            report.output().copied().ok_or(RecoveryError::NoStore)
        }
        Disposition::DeadlineExceeded => Err(RecoveryError::Deadline),
        Disposition::Cancelled => match index {
            Some(index) => Err(RecoveryError::Unit { index }),
            None => Err(RecoveryError::Deadline),
        },
        Disposition::Refused => Err(RecoveryError::NoStore),
        Disposition::Failed => {
            if let Some(index) = index {
                Err(RecoveryError::Unit { index })
            } else if report.error().map(is_time).unwrap_or(false) {
                Err(RecoveryError::Deadline)
            } else {
                Err(RecoveryError::NoStore)
            }
        }
    }
}

fn failed_index(progress: &Shared) -> Option<u32> {
    progress.lock().ok().and_then(|slot| slot.failed)
}

fn is_finished(progress: &Shared) -> bool {
    progress.lock().map(|slot| slot.finished).unwrap_or(false)
}

fn is_time(err: &FlowError) -> bool {
    err.is_cancelled() || matches!(err, FlowError::TimedOut { .. })
}

#[allow(unreachable_patterns)]
fn unit_index(err: &UnitError) -> Option<u32> {
    match err {
        UnitError::Unit { index } => Some(*index),
        _ => None,
    }
}

/// A run identity that is stable across attempts: it is derived from the store
/// itself, so every call with the same `store_dir` finds the records the first
/// call committed. No fresh randomness is involved.
fn run_id(store_dir: &Path) -> Result<RunId, RecoveryError> {
    let key = store_key(store_dir);
    let mut low = FNV_OFFSET;
    let mut high = FNV_OFFSET ^ SEED;
    for byte in key.as_bytes() {
        let value = u64::from(*byte);
        low = (low ^ value).wrapping_mul(FNV_PRIME);
        high = (high ^ value).wrapping_add(FNV_PRIME).rotate_left(7);
    }
    // `from_hex` rejects an all-zero identity; never ask it for one.
    if low == 0 {
        low = 1;
    }
    if high == 0 {
        high = 1;
    }
    RunId::from_hex(&format!("{low:016x}{high:016x}")).map_err(|_| RecoveryError::NoStore)
}

/// The store's own identity. The directory is created first so that the key
/// does not depend on whether this call or a later one saw it already there.
fn store_key(store_dir: &Path) -> String {
    let _ = std::fs::create_dir_all(store_dir);
    match std::fs::canonicalize(store_dir) {
        Ok(path) => path.to_string_lossy().into_owned(),
        Err(_) => store_dir.to_string_lossy().into_owned(),
    }
}

use std::num::NonZeroUsize;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{remember, within, FlowError, Scope};
use lgwks_bot::task::{task, Host};

/// One run identity, fixed for every attempt: the resume must find the
/// first attempt's records in `store_dir`.
const RUN_HEX: &str = "9f2c1a4b7d3e5f6081a2b3c4d5e6f708";

const TENANT: &str = "recover";
const TASK: &str = "recover";
const EFFECT: &str = "recover";
const LEDGER_STEP: &str = "ledger";

const NO_UNIT: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .max_concurrent_tasks(NonZeroUsize::new(4).ok_or(RecoveryError::NoStore)?)
        .default_deadline(deadline)
        .progress_capacity(world.width() as usize + 8)
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let worker = world.clone();
    let budget = deadline;
    let failed = Arc::new(AtomicU32::new(NO_UNIT));
    let seen = Arc::clone(&failed);

    let work = task(TASK, move |scope: Scope, _: ()| {
        let world = worker.clone();
        let failed = Arc::clone(&seen);
        async move { body(scope, world, budget, failed).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let outcome = host.resume(run, &work, ()).await.into_result();

    match outcome {
        Ok(total) => {
            let ledger = world.ledger();
            if ledger.applies() != 1 {
                return Err(RecoveryError::NoLedger);
            }
            Ok(total)
        }
        Err(FlowError::TimedOut { .. }) | Err(FlowError::Cancelled { .. }) => {
            Err(RecoveryError::Deadline)
        }
        Err(_) => {
            let index = failed.load(Ordering::SeqCst);
            if index == NO_UNIT {
                Err(RecoveryError::NoLedger)
            } else {
                Err(RecoveryError::Unit { index })
            }
        }
    }
}

/// The one task body: built once, used by the first attempt and every resume.
/// Units record themselves through `remember` under `unit_step(index)`, so a
/// replayed attempt never re-runs a committed body.
async fn body(
    scope: Scope,
    world: World,
    budget: Duration,
    failed: Arc<AtomicU32>,
) -> Result<u64, FlowError> {
    let work = async {
        let mut total: u64 = 0;
        for index in 0..world.width() {
            match world.unit(&scope, index).await {
                Ok(value) => total = total.saturating_add(value),
                Err(_) => {
                    failed.store(index, Ordering::SeqCst);
                    return Err(FlowError::failed(std::io::Error::other("unit")));
                }
            }
        }

        // The effect is inside a record, so it is applied on the first attempt
        // that reaches it and never again on any resume.
        remember(&scope, LEDGER_STEP, || async {
            let ledger = world.ledger();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok::<u64, FlowError>(0)
        })
        .await?;

        Ok(total)
    };

    within(&scope, "work", budget, work).await
}

//! Crash-tolerant recovery: units run at most once per store, the ledger effect
//! lands exactly once across attempts, and the overall deadline bounds it all.

use std::num::NonZeroUsize;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::Arc;
use std::time::Duration;

use lgwks_bot::script::FlowError;

/// The run identity: fixed text, so every attempt finds the first one's records.
const RUN_HEX: &str = "0123456789abcdef0123456789abcdef";

/// The one ledger effect.
const LEDGER: &str = "recover";

const NO_FAULT: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let width = world.width();
    let run =
        lgwks_bot::effect::RunId::from_hex(RUN_HEX).map_err(|_| RecoveryError::NoStore)?;
    let fan = NonZeroUsize::new(8);
    let fault = Arc::new(AtomicU32::new(NO_FAULT));

    // A durable store installed on the host, so a unit's `remember` has
    // somewhere to land and a later attempt replays it instead of re-running.
    let host = lgwks_bot::task::Host::builder("recovery")
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .progress_capacity(width as usize * 2 + 16)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    // The body is built once here; the resume drives it.
    let owned = Arc::new(world);
    let task = lgwks_bot::task::task("recover", move |scope, _input: ()| {
        let world = owned.clone();
        let fault = fault.clone();
        async move {
            let values = lgwks_bot::script::each(
                &scope,
                "units",
                fan,
                0u32..width,
                move |step, index| {
                    let world = world.clone();
                    let fault = fault.clone();
                    async move {
                        world.unit(&step, index).await.map_err(|err| {
                            let ai_task_support::recovery::UnitError::Unit { index } = err;
                            fault.store(index, Ordering::Relaxed);
                            FlowError::failed(format!("unit {index} failed"))
                        })
                    }
                },
            )
            .await?;

            let total: u64 = values.into_iter().sum();

            // Reading `applied` first is the only dedup the ledger offers, so the
            // effect lands exactly once even when both attempts reach this point.
            if !world.ledger().applied(LEDGER) {
                world.ledger().apply(LEDGER);
            }

            Ok(total)
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &task, ()).await;

    if !report.disposition().is_success() {
        let index = fault.load(Ordering::Relaxed);
        return Err(if index == NO_FAULT {
            RecoveryError::Deadline
        } else {
            RecoveryError::Unit { index }
        });
    }

    report.into_result().map_err(|_| RecoveryError::Deadline)
}

//! `recover` drives every unit of an [`ai_task_support::recovery::World`] to
//! completion across any number of attempts, applying its single ledger effect
//! exactly once.
//!
//! Three things make that possible:
//!
//! * a **run identity** derived deterministically from `store_dir`, so a later
//!   attempt resolves the same run and finds the earlier attempt's records;
//! * a **durable run store** installed on the `Host` before it runs, so a unit's
//!   `remember` has somewhere to land;
//! * the **task body built once** and replayed by `Host::resume` on every call.

use std::future::Future;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::atomic::{AtomicU32, Ordering};
use std::time::Duration;

use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, Tenant, within};
use lgwks_bot::task::{Host, Task, task};

use ai_task_support::recovery::{UnitError, World};

/// The ledger effect `recover` owns.
const EFFECT: &str = "recover";

/// The tenant the host and the task run under.
const TENANT: &str = "recover";

/// Sentinel meaning "no unit has failed".
const NO_UNIT: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// The unit input: the world to drive, plus the slot the first failing index is
/// published into, since the body is replayed on a later attempt.
struct Attempt {
    world: World,
    failed: Arc<AtomicU32>,
}

/// Cancels the host when dropped, so a caller that drops the `recover` future
/// mid-run leaves no unit body live.
struct CancelOnDrop {
    host: Host,
    armed: bool,
}

impl CancelOnDrop {
    fn new(host: Host) -> Self {
        Self { host, armed: true }
    }

    /// Called once the attempt has finished: the host must not be cancelled
    /// after its records have been committed.
    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        if self.armed {
            self.host.cancel();
        }
    }
}

/// The task body, built once per `recover` call and replayed by `Host::resume`.
///
/// Units are driven in order. A unit that succeeds has recorded its own value
/// durably, so a resumed attempt replays that value instead of running its body
/// again; the first unit that fails is published and the body returns, leaving
/// that unit unrecorded so a later call picks up exactly there.
async fn body(scope: Scope, attempt: Attempt) -> Result<u64, FlowError> {
    let Attempt { world, failed } = attempt;
    let width = world.width();
    let mut total: u64 = 0;

    for index in 0..width {
        match world.unit(&scope, index).await {
            Ok(value) => total = total.saturating_add(value),
            Err(UnitError::Unit { index: failed_at }) => {
                failed.store(failed_at, Ordering::SeqCst);
                return Ok(total);
            }
            Err(_) => {
                failed.store(index, Ordering::SeqCst);
                return Ok(total);
            }
        }
    }

    // Every unit is done, so the single effect this run owns can be applied.
    // `applied` is the only deduplication available: a resumed attempt reads it
    // first and skips, so the effect is applied exactly once across all calls.
    let ledger = world.ledger();
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }

    Ok(total)
}

/// The one path both the first attempt and the resume go through. Every call
/// uses `resume`, which runs what this run has not yet recorded and replays the
/// rest.
async fn attempt<F, Fut>(
    host: &Host,
    run: RunId,
    task: &Task<F>,
    attempt: Attempt,
) -> Result<u64, FlowError>
where
    F: Fn(Scope, Attempt) -> Fut,
    Fut: Future<Output = Result<u64, FlowError>>,
{
    host.resume(run, task, attempt).await.into_result()
}

/// A run identity that is a pure function of `store_dir`: the same directory
/// always means the same run, so every attempt finds the previous attempt's
/// records without needing a fresh random value.
fn run_id(store_dir: &Path) -> Result<RunId, RecoveryError> {
    let (hi, lo) = digest(store_dir.to_string_lossy().as_bytes());
    // Each lane is forced non-zero, so the 32 hex characters are never all zero.
    RunId::from_hex(&format!("{hi:016x}{lo:016x}")).map_err(|_| RecoveryError::NoStore)
}

/// FNV-1a over the path, folded into two independent 64-bit lanes.
fn digest(bytes: &[u8]) -> (u64, u64) {
    const PRIME: u64 = 0x0000_0100_0000_01b3;
    const SEED: u64 = 0xcbf2_9ce4_8422_2325;

    let mut hi = SEED;
    let mut lo = SEED ^ 0x9e37_79b9_7f4a_7c15;
    for byte in bytes {
        hi ^= u64::from(*byte);
        hi = hi.wrapping_mul(PRIME);
        lo = lo.wrapping_add(hi).rotate_left(31).wrapping_mul(PRIME);
    }
    (hi | 1, lo | 1)
}

fn is_deadline(err: &FlowError) -> bool {
    matches!(err, FlowError::TimedOut { .. } | FlowError::Cancelled { .. })
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = run_id(&store_dir)?;
    let failed = Arc::new(AtomicU32::new(NO_UNIT));

    // A durable run store, so a unit's `remember` lands on disk and the host
    // replays those records on the next attempt. Without one nothing survives.
    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .run_store(&store_dir)
        .map_err(|_| RecoveryError::NoStore)?;
    let host = builder
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;
    let mut guard = CancelOnDrop::new(host);

    let task = task("recover", body).map_err(|_| RecoveryError::NoStore)?;
    let scope = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?);

    // The deadline is honoured twice over: by the host's own default deadline,
    // and by racing the whole attempt against it here. Either way the attempt is
    // dropped -- and the host cancelled -- so no further unit is applied and no
    // unit body is left running.
    let unit = Attempt { world, failed: Arc::clone(&failed) };
    let outcome = within(
        &scope,
        "attempt",
        deadline,
        attempt(&guard.host, run, &task, unit),
    )
    .await;

    if outcome.is_err() {
        guard.host.cancel();
    }
    guard.disarm();

    let failed_index = failed.load(Ordering::SeqCst);
    match outcome {
        Ok(total) if failed_index == NO_UNIT => Ok(total),
        Ok(_) => Err(RecoveryError::Unit { index: failed_index }),
        Err(err) if is_deadline(&err) => Err(RecoveryError::Deadline),
        Err(_) if failed_index != NO_UNIT => Err(RecoveryError::Unit { index: failed_index }),
        // Not a timeout and no unit reported a failure: the run itself could
        // not be completed.
        Err(_) => Err(RecoveryError::NoStore),
    }
}

//! Recovery of a world of units across attempts.
//!
//! Every attempt of one recovery uses the same run identity and the same
//! durable store, so a step whose record is already committed replays its
//! recorded value instead of running its body again. The single ledger effect
//! is guarded by reading `applied` before applying it, so it lands exactly once
//! across any number of attempts.

use std::num::NonZeroUsize;
use std::sync::Arc;
use std::sync::atomic::{AtomicU32, Ordering};

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};
use lgwks_bot::task::{Host, task};

/// The run identity shared by every attempt of this recovery: the same text is
/// the same run, so a later attempt finds the earlier attempt's records.
const RUN: &str = "1f0e2d3c4b5a69788796a5b4c3d2e1f0";

/// The tenant, the task, the step and the ledger effect share this name.
const EFFECT: &str = "recover";

/// How many unit bodies may be in flight at once.
const POOL: Option<NonZeroUsize> = NonZeroUsize::new(4);

/// Sentinel meaning "no unit has reported a failure".
const NO_UNIT: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Drive every unit of `world` to completion, resuming whatever an earlier
/// attempt already recorded under `store_dir`.
pub async fn recover(
    world: World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    // A failing unit names itself here, because the failure is reported at the
    // item's path rather than handed back to us as an index.
    let failed = Arc::new(AtomicU32::new(NO_UNIT));

    let width = world.width() as usize;

    // A host with a durable run store: a unit's `remember` lands there, and the
    // records already in `store_dir` are replayed by `resume` below.
    let host = Arc::new(
        Host::builder(EFFECT)
            .map_err(|_| RecoveryError::NoStore)?
            .run_store(&store_dir)
            .map_err(|_| RecoveryError::NoStore)?
            .default_deadline(deadline)
            .progress_capacity(width.saturating_add(8))
            .build()
            .map_err(|_| RecoveryError::NoStore)?,
    );
    let guard = CancelHost(Arc::clone(&host));

    let run = RunId::from_hex(RUN).map_err(|_| RecoveryError::NoStore)?;

    // The task body is built once and used by every attempt, the first try and
    // the resume alike.
    let body = task(EFFECT, {
        let failed = Arc::clone(&failed);
        move |scope: Scope, _input: ()| {
            attempt(scope, Arc::new(world.clone()), Arc::clone(&failed))
        }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let outer = Scope::root(Tenant::new(EFFECT).map_err(|_| RecoveryError::NoStore)?);

    // Race the whole attempt against the deadline; on expiry the attempt is
    // dropped, which drops every unit body it owns.
    let outcome = within(&outer, EFFECT, deadline, async {
        host.resume(run, &body, ()).await.into_result()
    })
    .await;
    drop(guard);

    let index = failed.load(Ordering::SeqCst);
    match outcome {
        Ok(total) if index == NO_UNIT => Ok(total),
        Ok(_) => Err(RecoveryError::Unit { index }),
        Err(_) if index == NO_UNIT => Err(RecoveryError::Deadline),
        Err(_) => Err(RecoveryError::Unit { index }),
    }
}

/// The task body: the effect once, then every unit under its own recorded step,
/// then the total of the values they returned.
async fn attempt(
    scope: Scope,
    world: Arc<World>,
    failed: Arc<AtomicU32>,
) -> Result<u64, FlowError> {
    {
        let ledger = world.ledger();
        if !ledger.applied(EFFECT) {
            ledger.apply(EFFECT);
        }
    }

    let width = world.width();
    let values = each(&scope, "units", POOL, 0u32..width, move |step, index| {
        let world = Arc::clone(&world);
        let failed = Arc::clone(&failed);
        async move {
            world.unit(&step, index).await.map_err(|err| {
                if let UnitError::Unit { index } = err {
                    failed.store(index, Ordering::SeqCst);
                }
                FlowError::failed(String::from("a unit did not complete"))
            })
        }
    })
    .await?;

    Ok(values.iter().sum())
}

/// A dropped attempt must not leave a host driving unit bodies.
struct CancelHost(Arc<Host>);

impl Drop for CancelHost {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

//! Durable recovery of a partially applied world of units.
//!
//! The run identity is derived from `store_dir` alone, so every attempt at the
//! same store is the *same* run: the records written by a killed attempt are
//! replayed instead of being executed again. The task body is built once per
//! call from a single helper so the first attempt and the resume execute the
//! same steps, and the ledger effect is guarded by a durable step of its own so
//! it is applied exactly once across attempts.

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{unit_step, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{self, FlowError, Scope};
use lgwks_bot::task::{self, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TENANT: &str = "recovery";
const TASK_NAME: &str = "recover";
const UNITS_STEP: &str = "units";
const WORK_STEP: &str = "work";
const EFFECT_STEP: &str = "effect";
const EFFECT_NAME: &str = "recover";
const FANOUT: usize = 8;

/// The lowest index whose unit body has failed so far on this attempt.
#[derive(Clone)]
struct Failures(Arc<Mutex<Option<u32>>>);

impl Failures {
    fn new() -> Self {
        Failures(Arc::new(Mutex::new(None)))
    }

    fn note(&self, index: u32) {
        if let Ok(mut slot) = self.0.lock() {
            *slot = Some(match *slot {
                Some(seen) if seen <= index => seen,
                _ => index,
            });
        }
    }

    fn seen(&self) -> bool {
        match self.0.lock() {
            Ok(slot) => slot.is_some(),
            Err(_) => true,
        }
    }

    fn first(&self) -> Option<u32> {
        match self.0.lock() {
            Ok(slot) => *slot,
            Err(_) => Some(0),
        }
    }
}

/// The task body, shared by the first attempt and every resume.
async fn run_body(
    world: World,
    failures: Failures,
    scope: Scope,
    deadline: Duration,
) -> Result<u64, FlowError> {
    let work = async {
        let width = world.width();
        let bound = script::at_most(FANOUT)?;
        let world_ref: &World = &world;
        let failures_ref: &Failures = &failures;

        let values: Vec<u64> = script::each(
            &scope,
            UNITS_STEP,
            Some(bound),
            0u32..width,
            move |step, index| {
                let world = (*world_ref).clone();
                let failures = (*failures_ref).clone();
                async move {
                    // A unit already known to have failed: start nothing further,
                    // and record nothing, so a later attempt still runs it.
                    if failures.seen() {
                        return Ok::<u64, FlowError>(0);
                    }
                    let name = unit_step(index);
                    let step_ref: &Scope = &step;
                    let world_ref: &World = &world;
                    let failures_ref: &Failures = &failures;
                    // The body runs once per run; a resumed attempt replays the
                    // recorded value and never enters the body again.
                    let value: u64 = script::remember(
                        step_ref,
                        &name,
                        move || async move {
                            match world_ref.unit(step_ref, index).await {
                                Ok(value) => Ok(value),
                                Err(_) => {
                                    failures_ref.note(index);
                                    Ok(0)
                                }
                            }
                        },
                    )
                    .await?;
                    Ok::<u64, FlowError>(value)
                }
            },
        )
        .await?;

        if failures.seen() {
            return Ok(0);
        }

        let total: u64 = values.into_iter().sum();

        // The effect is applied from inside a recorded step, so a resumed
        // attempt replays the record instead of applying the effect again; the
        // ledger check covers an attempt that never got as far as recording.
        let ledger_world: &World = &world;
        let _marker: u64 = script::remember(&scope, EFFECT_STEP, move || async move {
            if !ledger_world.ledger().applied(EFFECT_NAME) {
                ledger_world.ledger().apply(EFFECT_NAME);
            }
            Ok::<u64, FlowError>(0)
        })
        .await?;

        Ok::<u64, FlowError>(total)
    };

    // Dropping this body on the deadline drops every unit body it owns.
    script::within(&scope, WORK_STEP, deadline, work).await
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let _ = std::fs::create_dir_all(&store_dir);
    let run = run_identity(&store_dir)?;
    let host = host_for(&store_dir, deadline)?;

    let failures = Failures::new();
    let body_world = world.clone();
    let body_failures = failures.clone();
    let handle = task::task(TASK_NAME, move |scope: Scope, _input: ()| {
        run_body(body_world.clone(), body_failures.clone(), scope, deadline)
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.resume(run, &handle, ()).await;

    if let Some(index) = failures.first() {
        return Err(RecoveryError::Unit { index });
    }

    // Anything else that did not finish is the deadline: the body was dropped
    // mid-flight, leaving no unit running.
    report.into_result().map_err(|_| RecoveryError::Deadline)
}

fn host_for(store_dir: &Path, deadline: Duration) -> Result<Host, RecoveryError> {
    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder.default_deadline(deadline);
    let builder = builder
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?;
    builder.build().map_err(|_| RecoveryError::NoStore)
}

fn fnv1a(bytes: &[u8], seed: u64) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64 ^ seed;
    for byte in bytes {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

/// A run identity that is a pure function of the store directory: the same
/// text on every attempt, so the second call finds the first call's records.
fn run_identity(store_dir: &Path) -> Result<RunId, RecoveryError> {
    let text = store_dir.to_string_lossy();
    let low = fnv1a(text.as_bytes(), 0x243f_6a88_85a3_08d3);
    let high = fnv1a(text.as_bytes(), 0x1319_8a2e_0370_7344);
    let hex = format!("{:016x}{:016x}", low, high);
    let hex = if hex.bytes().all(|b| b == b'0') {
        format!("{}1", "0".repeat(31))
    } else {
        hex
    };
    RunId::from_hex(&hex).map_err(|_| RecoveryError::NoStore)
}

use std::future::Future;
use std::num::NonZeroUsize;
use std::path::{Path, PathBuf};
use std::pin::Pin;
use std::sync::Arc;
use std::sync::atomic::{AtomicU32, Ordering};
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope, Tenant, at_most, each, within};
use lgwks_bot::task::{Host, Task};

const TENANT: &str = "recovery";
const TASK: &str = "recover";
const UNITS_STEP: &str = "units";
const EFFECT: &str = "recover";

/// Sentinel for "no unit has failed" in the shared marker.
const NO_UNIT: u32 = u32::MAX;

type Step = Pin<Box<dyn Future<Output = Result<u64, FlowError>>>>;
type Body = Box<dyn Fn(Scope, ()) -> Step>;
type RecoverTask = Task<Body>;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    // The failing unit is carried out of the fan-out, where the error is located
    // at the item's path, so the report cannot be inspected for it directly.
    let failed = Arc::new(AtomicU32::new(NO_UNIT));
    let marker = Arc::clone(&failed);

    // Built once from an owned `World`, so the task body is `'static` and the
    // same task is reused by the first attempt and by every resume.
    let task = recovery_task(world.clone(), failed)?;
    let host = install(&store_dir, deadline, world.width())?;
    let run = run_id(&store_dir)?;
    let outer = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?);

    // The run id is derived from the store, so the first attempt and every
    // resume are the same run: each attempt replays what the store recorded.
    // The outer `within` owns the resume future, so the deadline -- and a drop
    // of this future -- take the fan-out and every unit body down with it.
    let attempt = async move { Ok::<_, FlowError>(host.resume(run, &task, ()).await) };

    match within(&outer, TASK, deadline, attempt).await {
        Ok(report) => match report.into_result() {
            Ok(total) => Ok(total),
            Err(err) => Err(classify(&err, &marker)),
        },
        Err(err) => Err(classify(&err, &marker)),
    }
}

/// Built once and reused by the first attempt and by every resume: the same
/// task under the same run id replays the records the store already holds.
fn recovery_task(world: World, failed: Arc<AtomicU32>) -> Result<RecoverTask, RecoveryError> {
    let width = world.width();
    let fan_out = bound((width as usize).saturating_add(1).min(64))?;

    let body = move |scope: Scope, _input: ()| -> Step {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        Box::pin(async move {
            // Taken before the fan-out borrows the world for its bodies.
            let ledger = world.ledger();
            let runner = world.clone();

            let values = each(
                &scope,
                UNITS_STEP,
                Some(fan_out),
                0u32..width,
                move |step, index: u32| {
                    let world = runner.clone();
                    let failed = Arc::clone(&failed);
                    async move {
                        world.unit(&step, index).await.map_err(|err| {
                            let bad = match err {
                                UnitError::Unit { index } => index,
                                _ => index,
                            };
                            failed.store(bad, Ordering::SeqCst);
                            FlowError::failed(format!("unit {bad} failed"))
                        })
                    }
                },
            )
            .await?;

            // Applied only on the attempt that actually gets past every unit,
            // and only ever once across attempts: the ledger is shared by the
            // first attempt and the resume, and `applied` is the only dedup.
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }

            Ok(values.into_iter().sum())
        })
    };

    lgwks_bot::task::task(TASK, Box::new(body) as Body).map_err(|_| RecoveryError::NoStore)
}

/// A durable run store gives `remember` somewhere to land, so a unit whose
/// record is committed is not run again by a later attempt at the same step.
fn install(dir: &Path, deadline: Duration, width: u32) -> Result<Host, RecoveryError> {
    Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .max_concurrent_tasks(bound(1)?)
        .default_deadline(deadline)
        .progress_capacity(width as usize + 8)
        .run_store(dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)
}

fn bound(limit: usize) -> Result<NonZeroUsize, RecoveryError> {
    at_most(limit.max(1)).map_err(|_| RecoveryError::NoStore)
}

fn run_id(dir: &Path) -> Result<RunId, RecoveryError> {
    RunId::from_hex(&run_hex(dir)).map_err(|_| RecoveryError::NoStore)
}

/// Derived from the store, not freshly random: the same `store_dir` names the
/// same run on every attempt, which is what makes the second call a resume.
fn run_hex(dir: &Path) -> String {
    let text = dir.to_string_lossy();
    let (mut hi, mut lo) = (0xcbf2_9ce4_8422_2325u64, 0x9e37_79b9_7f4a_7c15u64);
    for &byte in text.as_bytes() {
        hi = (hi ^ byte as u64).wrapping_mul(0x0000_0100_0000_01b3);
        lo = (lo ^ (byte as u64).rotate_left(31)).wrapping_mul(0xff51_afd7_ed55_8ccd);
    }
    if hi == 0 && lo == 0 {
        hi = 1;
    }
    format!("{hi:016x}{lo:016x}")
}

fn classify(err: &FlowError, failed: &AtomicU32) -> RecoveryError {
    let index = failed.load(Ordering::SeqCst);
    if index != NO_UNIT {
        return RecoveryError::Unit { index };
    }
    if err.is_cancelled()
        || matches!(err, FlowError::Cancelled { .. } | FlowError::TimedOut { .. })
    {
        return RecoveryError::Deadline;
    }
    RecoveryError::NoStore
}
